  var ops=RegistryOps.create(JsonOps.INSTANCE,server.registryAccess());var encoded=Banks.CODEC.encodeStart(ops,b).getOrThrow();var decoded=Banks.CODEC.parse(ops,encoded).getOrThrow();check(decoded.entries.get(key).count()==4,"saved-data codec roundtrip");decoded.take(key,4);check(decoded.entries.isEmpty(),"stock exhaustion removes entry");
  model.typeLine="Basic Land — Forest";model.name="Integration Forest";model.id="3e76d43e-347c-4b68-ae11-3cac1a58440b";var land=CardStackBuilders.buildScryfallStackFromModel(model,false);check(Banks.kind(land)==0,"land classification");b.add(land,0,9999);String lk=Banks.key(0,land);check(b.entries.get(lk).count()==1,"unlimited catalogue stores template");b.take(lk,99);check(b.entries.containsKey(lk),"unlimited copies do not exhaust catalogue");
