  check(DeckboxTransfer.deposit(player,box,transfer)==1,"repeat deposit");check(DeckboxTransfer.deposit(player,box,transfer)==0,"repeat action does not duplicate deposit");transfer.add(card,2,200);check(DeckboxTransfer.withdraw(player,box,transfer,null,"",99)==98,"fill respects 99 main slots and existing land");check(!DeckboxTransfer.load(player,box).items().get(99).isEmpty(),"withdraw leaves special token slot");
